SELECT TABLE_NAME, COLUMN_NAME, DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='crypto_ai' AND TABLE_NAME IN ('candle_analysis_outcome','signal_processing_work') ORDER BY TABLE_NAME, ORDINAL_POSITION;
